'use strict';

// UTC-safe date helpers. All math goes through Date.UTC to avoid timezone drift.

const MS_PER_DAY = 24 * 60 * 60 * 1000;

const HOLIDAYS = new Set([
  '2025-01-01',
  '2025-07-04',
  '2025-11-27',
  '2025-12-25',
]);

// Strictly parse "YYYY-MM-DD" into a UTC timestamp, rejecting anything else
// (including out-of-range values like 2025-02-30 that Date.UTC would silently roll over).
function parseISODate(s) {
  if (typeof s !== 'string') return null;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  if (!m) return null;
  const y = Number(m[1]);
  const mo = Number(m[2]);
  const d = Number(m[3]);
  if (mo < 1 || mo > 12 || d < 1 || d > 31) return null;
  const t = Date.UTC(y, mo - 1, d);
  // Round-trip check catches e.g. Feb 30 -> Mar 2 overflow
  if (formatUTC(t) !== s) return null;
  return t;
}

function formatUTC(t) {
  const dt = new Date(t);
  const y = String(dt.getUTCFullYear()).padStart(4, '0');
  const mo = String(dt.getUTCMonth() + 1).padStart(2, '0');
  const d = String(dt.getUTCDate()).padStart(2, '0');
  return `${y}-${mo}-${d}`;
}

function dayOfWeekUTC(t) {
  return new Date(t).getUTCDay(); // 0=Sun .. 6=Sat
}

function isWeekend(t) {
  const dow = dayOfWeekUTC(t);
  return dow === 0 || dow === 6;
}

function isHoliday(t) {
  return HOLIDAYS.has(formatUTC(t));
}

// Add `days` calendar days, then roll forward past weekends and holidays.
// Returns { deadline, rolled }.
function rollDeadline(triggerISO, days) {
  let t = parseISODate(triggerISO);
  if (t === null) throw new TypeError('invalid trigger date');
  if (!Number.isInteger(days) || days < 1) throw new RangeError('days must be an integer >= 1');

  t += days * MS_PER_DAY;

  let rolled = false;
  while (isWeekend(t) || isHoliday(t)) {
    t += MS_PER_DAY;
    rolled = true;
  }
  return { deadline: formatUTC(t), rolled };
}

module.exports = { rollDeadline, parseISODate, formatUTC, isWeekend, isHoliday, HOLIDAYS };

