'use strict';

const http = require('node:http');
const { rollDeadline, HOLIDAYS } = require('./deadline');

const HOST = process.env.HOST || '127.0.0.1';
const PORT = Number(process.env.PORT) || 8492;

function sendJSON(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(body),
  });
  res.end(body);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (chunk) => {
      data += chunk;
      if (data.length > 64 * 1024) {
        reject(new Error('payload too large'));
        req.destroy();
      }
    });
    req.on('end', () => resolve(data));
    req.on('error', reject);
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);

  try {
    if (req.method === 'GET' && url.pathname === '/holidays') {
      return sendJSON(res, 200, { holidays: [...HOLIDAYS].sort() });
    }

    if (req.method === 'POST' && url.pathname === '/deadline') {
      let parsed;
      try {
        parsed = JSON.parse(await readBody(req));
      } catch {
        return sendJSON(res, 422, { error: 'request body must be valid JSON' });
      }

      const { trigger, days } = parsed ?? {};
      if (typeof trigger !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(String(trigger))) {
        return sendJSON(res, 422, { error: 'trigger must be a date string in YYYY-MM-DD format' });
      }
      if (!Number.isInteger(days) || days < 1) {
        return sendJSON(res, 422, { error: 'days must be an integer >= 1' });
      }

      try {
        const result = rollDeadline(trigger, days);
        return sendJSON(res, 200, result);
      } catch {
        return sendJSON(res, 422, { error: 'invalid trigger date' });
      }
    }

    return sendJSON(res, 404, { error: 'not found' });
  } catch (err) {
    return sendJSON(res, 500, { error: 'internal server error' });
  }
});

if (require.main === module) {
  server.listen(PORT, HOST, () => {
    console.log(`deadline service listening on http://${HOST}:${PORT}`);
  });
}

module.exports = { server };

process.on('SIGTERM', () => server.close(() => process.exit(0)));
process.on('SIGINT', () => server.close(() => process.exit(0)));

