'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { rollDeadline, parseISODate, isWeekend } = require('./deadline');

test('plain weekday addition rolls nothing', () => {
  // 2025-03-10 is a Monday; +5 lands Friday 2025-03-15
  assert.deepEqual(rollDeadline('2025-03-10', 5), { deadline: '2025-03-15', rolled: false });
});

test('Friday +1 lands Saturday and rolls over weekend to Monday', () => {
  // 2025-01-03 is a Friday; +1 -> Sat 01-04 -> Sun -> Mon 01-06
  assert.deepEqual(rollDeadline('2025-01-03', 1), { deadline: '2025-01-06', rolled: true });
});

test('rolls forward over a holiday (Christmas)', () => {
  assert.deepEqual(rollDeadline('2025-12-24', 1), { deadline: '2025-12-26', rolled: true });
});

test('year boundary: 2025-12-31 + 3 crosses into 2026 and rolls off the Saturday', () => {
  // +3 -> Sat 2026-01-03 -> Sun -> Mon 2026-01-05
  assert.deepEqual(rollDeadline('2025-12-31', 3), { deadline: '2026-01-05', rolled: true });
});

test('New Year holiday roll at year boundary', () => {
  // 2024-12-30 Tue +2 -> Thu 2025-01-02? No: +2 = 2025-01-01 which is a holiday
  // -> rolls to Thursday 2025-01-02
  assert.deepEqual(rollDeadline('2024-12-30', 2), { deadline: '2025-01-02', rolled: true });
});

test('long roll spanning weekend plus holiday', () => {
  // 2025-11-26 Wed +1 -> Thanksgiving 11-27 -> Fri 11-28 -> Sat/Sun -> Mon 12-01
  assert.deepEqual(rollDeadline('2025-11-26', 1), { deadline: '2025-12-01', rolled: true });
});

test('July 4th holiday', () => {
  // 2025-07-03 Thu +1 -> holiday -> Fri 07-04 also holiday -> Sat/Sun -> Mon 07-07
  assert.deepEqual(rollDeadline('2025-07-03', 1), { deadline: '2025-07-07', rolled: true });
});

test('leap-year safe arithmetic (Feb 29 exists in 2024)', () => {
  // 2024-02-28 Wed +1 -> Thu 2024-02-29
  assert.deepEqual(rollDeadline('2024-02-28', 1), { deadline: '2024-02-29', rolled: false });
});

test('rejects invalid dates and days < 1', () => {
  assert.throws(() => rollDeadline('2025-02-30', 1));
  assert.throws(() => rollDeadline('2025-13-01', 1));
  assert.throws(() => rollDeadline('not-a-date', 1));
  assert.throws(() => rollDeadline('2025-01-01', 0));
  assert.throws(() => rollDeadline('2025-01-01', -5));
  assert.throws(() => rollDeadline('2025-01-01', 1.5));
});

test('parseISODate rejects overflow dates that Date.UTC would accept', () => {
  assert.equal(parseISODate('2025-02-30'), null);
  assert.equal(parseISODate('2025-04-31'), null);
  assert.notEqual(parseISODate('2025-02-28'), null);
});

test('isWeekend uses UTC day-of-week (no local-time drift)', () => {
  const sat = Date.UTC(2025, 0, 4);
  assert.equal(isWeekend(sat), true);
});

